@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping
    public List<Order> getAllOrders() {
        return orderService.findAll(); // Stateless: no session tracking
    }

    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(ResponseEntity::ok) // 200 OK with order
            .orElse(ResponseEntity.notFound().build()); // 404 if not found
    }

    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        var saved = orderService.save(order);
        return ResponseEntity.status(HttpStatus.CREATED).body(saved); // 201 Created
    }
}

@RestController
@RequestMapping("/api")
public class UserOrderController {
    private final UserService userService;
    private final OrderService orderService;

    public UserOrderController(UserService userService, OrderService orderService) {
        this.userService = userService;
        this.orderService = orderService;
    }

    @GetMapping("/users") // Collection resource
    public List<User> getAllUsers(@RequestParam(required = false) String role) {
        return role != null ? userService.findByRole(role) : userService.findAll();
    }

    @GetMapping("/users/{userId}") // Singleton resource
    public ResponseEntity<User> getUser(@PathVariable Long userId) {
        return userService.findById(userId)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    @GetMapping("/users/{userId}/orders") // Nested collection resource
    public List<Order> getUserOrders(@PathVariable Long userId) {
        return orderService.findByUserId(userId); // Hierarchical relationship
    }

    @PostMapping("/orders") // Create in collection
    public ResponseEntity<Order> createOrder(@RequestBody Order order) {
        var saved = orderService.save(order);
        var location = URI.create("/api/orders/" + saved.getId());
        return ResponseEntity.created(location).body(saved); // 201 with Location header
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;
    private final JwtTokenProvider tokenProvider;

    public OrderController(OrderService orderService, JwtTokenProvider tokenProvider) {
        this.orderService = orderService;
        this.tokenProvider = tokenProvider;
    }

    @GetMapping
    public ResponseEntity<List<Order>> getUserOrders(
            @RequestHeader("Authorization") String bearerToken) {
        // Extract userId from JWT token in every request - no session
        var token = bearerToken.replace("Bearer ", "");
        var userId = tokenProvider.getUserIdFromToken(token); // Stateless: token contains user identity

        if (!tokenProvider.validateToken(token)) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();
        }

        var orders = orderService.findByUserId(userId);
        return ResponseEntity.ok(orders); // Each request is independent
    }

    @GetMapping("/{orderId}")
    public ResponseEntity<Order> getOrder(
            @RequestHeader("Authorization") String bearerToken,
            @PathVariable Long orderId) {
        var token = bearerToken.replace("Bearer ", "");
        var userId = tokenProvider.getUserIdFromToken(token);

        // Every request repeats authentication - no server-side session
        return orderService.findByIdAndUserId(orderId, userId)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }
}

@RestController
@RequestMapping("/api/products")
public class ProductController {
    private final ProductRepository repository;

    public ProductController(ProductRepository repository) {
        this.repository = repository; // Constructor injection
    }

    @GetMapping // GET /api/products
    public List<Product> getAllProducts(@RequestParam(required = false) String category) {
        return category != null 
            ? repository.findByCategory(category) 
            : repository.findAll();
    }

    @GetMapping("/{id}") // GET /api/products/42
    public ResponseEntity<Product> getProduct(@PathVariable Long id) {
        return repository.findById(id)
            .map(ResponseEntity::ok) // 200 OK
            .orElse(ResponseEntity.notFound().build()); // 404 Not Found
    }

    @PostMapping // POST /api/products with JSON body
    public ResponseEntity<Product> createProduct(@RequestBody Product product) {
        var saved = repository.save(product);
        var location = URI.create("/api/products/" + saved.getId());
        return ResponseEntity.created(location).body(saved); // 201 Created with Location header
    }

    @PutMapping("/{id}") // PUT /api/products/42
    public ResponseEntity<Product> updateProduct(
            @PathVariable Long id, 
            @RequestBody Product product) {
        if (!repository.existsById(id)) {
            return ResponseEntity.notFound().build(); // 404 if product doesn't exist
        }
        product.setId(id); // Ensure ID matches URI
        return ResponseEntity.ok(repository.save(product)); // 200 OK
    }

    @DeleteMapping("/{id}") // DELETE /api/products/42
    public ResponseEntity<Void> deleteProduct(@PathVariable Long id) {
        if (!repository.existsById(id)) {
            return ResponseEntity.notFound().build();
        }
        repository.deleteById(id);
        return ResponseEntity.noContent().build(); // 204 No Content
    }
}

